script:
$dns = @('1.1.1.1','1.0.0.1')
Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' } | ForEach-Object {
  Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ServerAddresses $dns
  Write-Host ('DNS set on ' + $_.Name) }
Clear-DnsClientCache

$dns = @('8.8.8.8','8.8.4.4')
Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' } | ForEach-Object {
  Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ServerAddresses $dns
  Write-Host ('DNS set on ' + $_.Name) }
Clear-DnsClientCache

$dns = @('9.9.9.9','149.112.112.112')
Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' } | ForEach-Object {
  Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ServerAddresses $dns
  Write-Host ('DNS set on ' + $_.Name) }
Clear-DnsClientCache

$dns = @('94.140.14.14','94.140.15.15')
Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' } | ForEach-Object {
  Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ServerAddresses $dns
  Write-Host ('DNS set on ' + $_.Name) }
Clear-DnsClientCache

'XblAuthManager','XblGameSave','XboxGipSvc','XboxNetApiSvc' | ForEach-Object {
  Set-Service -Name $_ -StartupType Manual -ErrorAction SilentlyContinue
  Write-Host ('Service ' + $_ + ' set to Manual') }

powercfg -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61 | Out-Null
$scheme = (powercfg /list | Select-String 'Ultimate Performance' | Select-Object -First 1)
if ($scheme -match '([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})') { powercfg /setactive $Matches[1]; Write-Host 'Ultimate Performance activated.' }
else { powercfg /setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c; Write-Host 'Fell back to High Performance.' }

$svc = @('Fax','RemoteRegistry','RetailDemo','MapsBroker','WalletService','PhoneSvc','MessagingService',
  'DiagTrack','dmwappushservice','diagnosticshub.standardcollector.service','DPS','WdiServiceHost','WdiSystemHost',
  'lfsvc','SharedAccess','WerSvc','PcaSvc','TabletInputService','SCardSvr','SEMgrSvc','SysMain','WpcMonSvc')
foreach ($s in $svc) {
  if (Get-Service -Name $s -ErrorAction SilentlyContinue) {
    Set-Service -Name $s -StartupType Manual -ErrorAction SilentlyContinue
    Write-Host ('  ' + $s + ' -> Manual') } }
Write-Host 'Service trim complete.'

Get-Volume | Where-Object { $_.DriveLetter -and $_.DriveType -eq 'Fixed' } | ForEach-Object {
  Write-Host ('Optimizing ' + $_.DriveLetter + ':')
  Optimize-Volume -DriveLetter $_.DriveLetter -ReTrim -Verbose -ErrorAction SilentlyContinue }

$k = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager'
$vals = @{ SubscribedContent-338388Enabled=0; SubscribedContent-338389Enabled=0; SubscribedContent-338393Enabled=0;
  SubscribedContent-353694Enabled=0; SubscribedContent-353696Enabled=0; SubscribedContent-310093Enabled=0;
  SubscribedContent-338387Enabled=0; SystemPaneSuggestionsEnabled=0; SilentInstalledAppsEnabled=0;
  SoftLandingEnabled=0; RotatingLockScreenOverlayEnabled=0; PreInstalledAppsEnabled=0; OemPreInstalledAppsEnabled=0 }
foreach ($n in $vals.Keys) { New-ItemProperty -Path $k -Name $n -Value $vals[$n] -PropertyType DWord -Force | Out-Null }
New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' -Force | Out-Null
New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' -Name DisableWindowsConsumerFeatures -Value 1 -PropertyType DWord -Force | Out-Null
New-ItemProperty -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' -Name DisableSoftLanding -Value 1 -PropertyType DWord -Force | Out-Null

$k = 'HKLM:\SOFTWARE\Policies\Microsoft\Edge'
New-Item -Path $k -Force | Out-Null
$vals = @{ MetricsReportingEnabled=0; SendSiteInfoToImproveServices=0; PersonalizationReportingEnabled=0;
  EdgeShoppingAssistantEnabled=0; ShowMicrosoftRewards=0; StartupBoostEnabled=0; BackgroundModeEnabled=0;
  UserFeedbackAllowed=0; DiagnosticData=0; EdgeCollectionsEnabled=0; HubsSidebarEnabled=0 }
foreach ($n in $vals.Keys) { New-ItemProperty -Path $k -Name $n -Value $vals[$n] -PropertyType DWord -Force | Out-Null }

'{f874310e-b6b7-47dc-bc84-b9e6b38f5903}','{e88865ea-0e1c-4e20-9aa6-edcd0212c87c}' | ForEach-Object {
  $k = 'HKCU:\Software\Classes\CLSID\' + $_
  New-Item -Path $k -Force | Out-Null
  New-ItemProperty -Path $k -Name 'System.IsPinnedToNameSpaceTree' -Value 0 -PropertyType DWord -Force | Out-Null }
New-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced' -Name LaunchTo -Value 1 -PropertyType DWord -Force | Out-Null

$ids = '{0DB7E03F-FC29-4DC6-9020-FF41B59E513A}','{3DFDF296-DBEC-4FB4-81D1-6A3438BCF4DE}','{A0953C92-50DC-43BF-BE83-3742FED03C9C}'
foreach ($id in $ids) {
  Remove-Item ('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\MyComputer\NameSpace\' + $id) -Recurse -Force -ErrorAction SilentlyContinue
  Remove-Item ('HKLM:\SOFTWARE\Wow6432Node\Microsoft\Windows\CurrentVersion\Explorer\MyComputer\NameSpace\' + $id) -Recurse -Force -ErrorAction SilentlyContinue }
Write-Host 'Legacy user folders removed from This PC.'

$p = Join-Path ([Environment]::GetFolderPath('Desktop')) 'God Mode.{ED7BA470-8E54-465E-825C-99712043E01C}'
if (-not (Test-Path $p)) { New-Item -Path $p -ItemType Directory | Out-Null }
Write-Host 'God Mode folder created on the desktop.'

Stop-Process -Name OneDrive -Force -ErrorAction SilentlyContinue
$setup = if (Test-Path "$env:SystemRoot\SysWOW64\OneDriveSetup.exe") { "$env:SystemRoot\SysWOW64\OneDriveSetup.exe" } else { "$env:SystemRoot\System32\OneDriveSetup.exe" }
if (Test-Path $setup) { Start-Process $setup -ArgumentList '/uninstall' -Wait -ErrorAction SilentlyContinue }
Remove-Item 'HKCU:\Software\Classes\CLSID\{018D5C66-4533-4307-9B53-224DE2ED1FE6}' -Recurse -Force -ErrorAction SilentlyContinue
Write-Host 'OneDrive removed.'

@('Microsoft.XboxApp','Microsoft.XboxGameOverlay','Microsoft.XboxGamingOverlay',
  'Microsoft.XboxSpeechToTextOverlay','Microsoft.XboxIdentityProvider','Microsoft.Xbox.TCUI') | ForEach-Object {
  Get-AppxPackage -Name $_ -AllUsers -ErrorAction SilentlyContinue | Remove-AppxPackage -AllUsers -ErrorAction SilentlyContinue
  Write-Host ('  removed ' + $_) }

Get-AppxPackage -AllUsers | ForEach-Object {
  Add-AppxPackage -DisableDevelopmentMode -Register ($_.InstallLocation + '\AppXManifest.xml') -ErrorAction SilentlyContinue }
Write-Host 'Default apps re-registered.'

$before = (Get-PSDrive C).Free
@("$env:TEMP\*", "$env:SystemRoot\Temp\*", "$env:SystemRoot\Prefetch\*") | ForEach-Object {
  Remove-Item $_ -Recurse -Force -ErrorAction SilentlyContinue }
$freed = [math]::Round(((Get-PSDrive C).Free - $before) / 1MB, 1)
Write-Host ('Temp cleaned — ' + $freed + ' MB freed.')

Get-WinEvent -ListLog * -ErrorAction SilentlyContinue | Where-Object { $_.RecordCount -gt 0 } | ForEach-Object {
  try { [System.Diagnostics.Eventing.Reader.EventLogSession]::GlobalSession.ClearLog($_.LogName) } catch {} }
Write-Host 'Event logs cleared.'

powercfg -setacvalueindex SCHEME_CURRENT 2a737441-1930-4402-8d77-b2bebba308a3 48e6b7a6-50f5-4782-a5d4-53bb8f07e226 0
powercfg -setactive SCHEME_CURRENT
Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Enum\USB' -ErrorAction SilentlyContinue | ForEach-Object {
  Get-ChildItem $_.PSPath -ErrorAction SilentlyContinue | ForEach-Object {
    $p = Join-Path $_.PSPath 'Device Parameters'
    if (Test-Path $p) { New-ItemProperty -Path $p -Name EnhancedPowerManagementEnabled -Value 0 -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null } } }
Write-Host 'USB selective suspend disabled.'
